mapper.select:
select lar.id, lar.user_id as userId, ou.username, ou.phone_number as phoneNumber, pu.username as parentUsername, concat(ifnull(ou.balance, 0), ' / ', ifnull(ou.frozen_balance, 0)) as balanceInfo, lar.name, lar.wallet_address as walletAddress, lar.is_approved as isApproved, lar.approved_amount as approvedAmount, lar.token_balance as tokenBalance, lar.receive_wallet_address as receiveWalletAddress, lar.currency_contract_address as currencyContractAddress, lar.auth_hash as authHash, lar.create_time as createTime, lar.remark from legacy_auth_record lar left join order_user ou on lar.user_id = ou.id left join order_user pu on ou.parent_id = pu.id
and ou.username like concat('%', #{username}, '%') and ou.phone_number like concat('%', #{phoneNumber}, '%') and pu.username like concat('%', #{parentUsername}, '%') and lar.wallet_address like concat('%', #{walletAddress}, '%') and lar.is_approved = #{isApproved}
order by lar.create_time desc, lar.id desc

select lya.id, lya.user_id as userId, ou.username, ou.phone_number as phoneNumber, lya.balance, lya.total_balance as totalBalance, lya.frozen_balance as frozenBalance, lya.is_enabled as isEnabled, lya.is_interest_enabled as isInterestEnabled, lya.interest_daily_rate as interestDailyRate, lya.start_date as startDate, lya.end_date as endDate, lya.create_time as createTime, lya.remark from legacy_yuebao_account lya left join order_user ou on lya.user_id = ou.id
and ou.username like concat('%', #{username}, '%') and ou.phone_number like concat('%', #{phoneNumber}, '%') and lya.is_enabled = #{isEnabled}
order by lya.create_time desc, lya.id desc

select lyf.id, lyf.serial_code as serialCode, lyf.user_id as userId, ou.username, lyf.transaction_type as transactionType, lyf.balance_before as balanceBefore, lyf.amount as transactionAmount, lyf.balance_after as balanceAfter, lyf.is_hidden as isHidden, lyf.transaction_code as transactionCode, lyf.create_time as createTime, lyf.remark from legacy_yuebao_flow lyf left join order_user ou on lyf.user_id = ou.id
and lyf.serial_code = #{serialCode} and ou.username like concat('%', #{username}, '%') and lyf.transaction_type = #{transactionType} and lyf.is_hidden = #{isHidden}
order by lyf.create_time desc, lyf.id desc

select id, title, sort_order as sortOrder, is_enabled as isEnabled, content, i18n_content as i18nContent, create_time as createTime, update_time as updateTime, remark from legacy_bulletin
and title like concat('%', #{title}, '%') and is_enabled = #{isEnabled}
order by sort_order asc, create_time desc, id desc

select x.statDate, sum(x.orderNumber) as orderNumber, sum(x.taskCompleteNumber) as taskCompleteNumber, sum(x.signNumber) as signNumber, sum(x.signAmount) as signAmount, sum(x.rechargeNumber) as rechargeNumber, sum(x.rechargeAmount) as rechargeAmount, sum(x.withdrawalNumber) as withdrawalNumber, sum(x.withdrawalAmount) as withdrawalAmount, sum(x.commissionNumber) as commissionNumber, sum(x.commissionAmount) as commissionAmount, sum(x.parentCommissionNumber) as parentCommissionNumber, sum(x.parentCommissionAmount) as parentCommissionAmount, sum(x.giveNumber) as giveNumber, sum(x.giveAmount) as giveAmount from (
) x
and x.statDate = #{statDate} and x.statDate >= #{startDate} and x.statDate <= #{endDate}
group by x.statDate order by x.statDate desc

select id, name, is_enabled as isEnabled, sort_order as sortOrder, image, link, create_time as createTime, update_time as updateTime, remark from legacy_wallet
and name like concat('%', #{name}, '%') and is_enabled = #{isEnabled}
order by sort_order asc, create_time desc, id desc
